// src/calculators/InternetSearchForm.jsx
import React, { useState } from 'react';
import { internetConfig } from '../config/config';

/**
 * onSelect(plan) 콜백으로 선택된 플랜을 전달합니다.
 * 플랜 종류(전체/일반/알뜰/패밀리), 명칭, 속도로 필터링합니다.
 */
export default function InternetSearchForm({ onSelect }) {
  const [category, setCategory] = useState('all');
  const [nameQuery, setNameQuery] = useState('');
  const [speedQuery, setSpeedQuery] = useState('');

  // 플랜 목록 필터링
  const filteredPlans = internetConfig.plans.filter(plan => {
    // 1) 카테고리 필터
    let categoryOK = true;
    if (category === 'general') {
      categoryOK = !plan.id.startsWith('altt_') && !plan.id.startsWith('family_');
    } else if (category === 'altt') {
      categoryOK = plan.id.startsWith('altt_');
    } else if (category === 'family') {
      categoryOK = plan.id.startsWith('family_');
    }

    // 2) 명칭 필터
    const nameOK =
      !nameQuery || plan.name.toLowerCase().includes(nameQuery.toLowerCase());

    // 3) 속도 필터
    const speedOK =
      !speedQuery || plan.speed.toLowerCase().includes(speedQuery.toLowerCase());

    return categoryOK && nameOK && speedOK;
  });

  return (
    <div className="space-y-6 mb-8">
      {/* 플랜 종류 선택 */}
      <div>
        <label className="block mb-1 font-medium">플랜 종류</label>
        <select
          value={category}
          onChange={e => setCategory(e.target.value)}
          className="w-full border rounded p-2"
        >
          <option value="all">전체</option>
          <option value="general">일반</option>
          <option value="altt">알뜰</option>
          <option value="family">패밀리</option>
        </select>
      </div>

      {/* 인터넷 명칭 검색 */}
      <div>
        <label className="block mb-1 font-medium">인터넷 명칭으로 검색</label>
        <div className="relative">
          <input
            type="text"
            value={nameQuery}
            onChange={e => setNameQuery(e.target.value)}
            placeholder="예) 인터넷 슈퍼프리미엄"
            className="w-full border rounded p-2 pr-10"
          />
          {nameQuery && (
            <button
              type="button"
              onClick={() => setNameQuery('')}
              className="absolute inset-y-0 right-2 flex items-center text-gray-400 hover:text-gray-600"
            >
              &times;
            </button>
          )}
        </div>
      </div>

      {/* 인터넷 속도 검색 */}
      <div>
        <label className="block mb-1 font-medium">인터넷 속도로 검색</label>
        <div className="relative">
          <input
            type="text"
            value={speedQuery}
            onChange={e => setSpeedQuery(e.target.value)}
            placeholder="예) 500Mbps, 1Gbps 등"
            className="w-full border rounded p-2 pr-10"
          />
          {speedQuery && (
            <button
              type="button"
              onClick={() => setSpeedQuery('')}
              className="absolute inset-y-0 right-2 flex items-center text-gray-400 hover:text-gray-600"
            >
              &times;
            </button>
          )}
        </div>
      </div>

      {/* 검색 결과 리스트 */}
      {(category !== 'all' || nameQuery || speedQuery) && (
        filteredPlans.length > 0 ? (
          <ul className="border rounded overflow-hidden">
            {filteredPlans.map(plan => (
              <li
                key={plan.id}
                onClick={() => onSelect(plan)}
                className="flex justify-between px-4 py-2 hover:bg-gray-100 cursor-pointer"
              >
                <span>{plan.name}</span>
                <span className="text-sm text-gray-500">({plan.speed})</span>
              </li>
            ))}
          </ul>
        ) : (
          <p className="text-center text-gray-500">조건에 맞는 플랜이 없습니다.</p>
        )
      )}
    </div>
  );
}
