import React, { useState } from 'react';
import { tvmConfig } from '../config/config';

/**
 * onSelect(plan) 콜백으로 선택된 플랜 전달
 */
export default function TvmSearchForm({ onSelect }) {
  const [nameQuery, setNameQuery] = useState('');
  const [channelQuery, setChannelQuery] = useState('');

  // 이름·채널 동시 필터링
  const filteredPlans = tvmConfig.plans.filter(p => {
    const nameOK = !nameQuery || p.name.toLowerCase().includes(nameQuery.toLowerCase());
    const channelOK = !channelQuery || String(p.channel).includes(channelQuery);
    return nameOK && channelOK;
  });

  return (
    <div className="space-y-6 mb-8">
      {/* TV 명칭 검색 */}
      <div>
        <label className="block mb-1 font-medium">TV 명칭으로 검색</label>
        <div className="relative">
          <input
            type="text"
            value={nameQuery}
            onChange={e => setNameQuery(e.target.value)}
            placeholder="예) TV 에센스"
            className="w-full border rounded p-2 pr-10"
          />
          {nameQuery && (
            <button
              type="button"
              onClick={() => setNameQuery('')}
              className="absolute inset-y-0 right-2 flex items-center text-gray-400 hover:text-gray-600"
            >
              &times;
            </button>
          )}
        </div>
      </div>

      {/* TV 채널 검색 */}
      <div>
        <label className="block mb-1 font-medium">TV 채널로 검색</label>
        <div className="relative">
          <input
            type="text"
            value={channelQuery}
            onChange={e => setChannelQuery(e.target.value)}
            placeholder="예) 236"
            className="w-full border rounded p-2 pr-10"
          />
          {channelQuery && (
            <button
              type="button"
              onClick={() => setChannelQuery('')}
              className="absolute inset-y-0 right-2 flex items-center text-gray-400 hover:text-gray-600"
            >
              &times;
            </button>
          )}
        </div>
      </div>

      {/* 검색 결과 리스트 */}
      {(nameQuery || channelQuery) && (
        filteredPlans.length > 0 ? (
          <ul className="border rounded overflow-hidden bg-white">
            {filteredPlans.map(plan => (
              <li
                key={plan.id}
                onClick={() => onSelect(plan)}
                className="flex justify-between px-4 py-2 hover:bg-gray-100 cursor-pointer"
              >
                <span>{plan.name}</span>
                <span className="text-sm text-gray-500">({plan.channel})</span>
              </li>
            ))}
          </ul>
        ) : (
          <p className="text-center text-gray-500">조건에 맞는 요금제가 없습니다.</p>
        )
      )}
    </div>
  );
}
