// src/calculators/InternetResult.jsx
import React from 'react';
import { internetConfig } from '../config/config';

/**
 * 선택된 인터넷 플랜의 가격표, 할인, 모뎀 이용료, 총금액을 표시합니다.
 * 알뜰 플랜은 일반 플랜의 3년 약정 가격을 모든 기간에 적용하고,
 * 그 위에 고정 할인 금액(-원)을 뺀 뒤 모뎀 요금을 더합니다.
 */
export default function InternetResult({ plan }) {
  const { id, name, speed } = plan;
  const originalPricing = plan.pricing;

  // 알뜰 플랜 판별 및 할인 금액
  const isAltt = id.startsWith('altt_');
  const discountMap = { altt_essence: 3300, altt_basic: 3000, altt_slim: 2750 };
  const discount = isAltt ? (discountMap[id] || 0) : 0;

  // 알뜰 플랜일 때 일반 플랜의 3년 약정 가격 가져오기
  let overrideBase = null;
  if (isAltt) {
    const generalId = id.replace('altt_', '');
    const generalPlan = internetConfig.plans.find(p => p.id === generalId);
    overrideBase = generalPlan?.pricing['3년'] ?? 0;
  }

  // 모뎀 이용료 설정: 프리미엄 또는 일반
  const premiumConfig = internetConfig.premiumModemFee[id] || {};
  const generalConfig = internetConfig.generalModemFee[id] || {};
  const isPremium = Object.keys(premiumConfig).length > 0;
  const feeConfig = isPremium ? premiumConfig : generalConfig;

  // 약정 기간 순서
  const terms = Object.keys(originalPricing);

  return (
    <div className="mb-8">
      <h2 className="text-xl font-semibold mb-4">
        선택된 플랜: {name} ({speed})
      </h2>
      <table className="w-full table-auto border-collapse">
        <thead>
          <tr className="bg-gray-100">
            <th className="border px-3 py-2">약정 기간</th>
            {terms.map(term => (
              <th key={term} className="border px-3 py-2">{term}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          {/* 월 요금 */}
          <tr>
            <td className="border px-3 py-2">월 요금(원)</td>
            {terms.map((term, idx) => {
              const base = isAltt ? overrideBase : originalPricing[term] || 0;
              return (
                <td key={idx} className="border px-3 py-2">
                  {base.toLocaleString()}
                </td>
              );
            })}
          </tr>
          {/* 알뜰 할인 */}
          {isAltt && (
            <tr>
              <td className="border px-3 py-2 text-red-600">알뜰 할인(원)</td>
              {terms.map((term, idx) => (
                <td key={idx} className="border px-3 py-2 text-red-600">
                  -{discount.toLocaleString()}
                </td>
              ))}
            </tr>
          )}
          {/* 월 모뎀 이용료 */}
          <tr>
            <td className="border px-3 py-2">월 모뎀 이용료(원)</td>
            {terms.map((term, idx) => {
              const fee = feeConfig[term] || 0;
              return (
                <td key={idx} className="border px-3 py-2">
                  {fee.toLocaleString()}
                </td>
              );
            })}
          </tr>
          {/* 월 총금액 (VAT 포함) */}
          <tr>
            <td className="border px-3 py-2 font-semibold">월 총금액(원) (VAT 포함)</td>
            {terms.map((term, idx) => {
              const base = isAltt ? overrideBase : originalPricing[term] || 0;
              const fee = feeConfig[term] || 0;
              const total = base - (isAltt ? discount : 0) + fee;
              return (
                <td key={idx} className="border px-3 py-2 font-semibold">
                  {total.toLocaleString()}
                </td>
              );
            })}
          </tr>
        </tbody>
      </table>
    </div>
  );
}
