// src/calculators/InternetCalculator.jsx
import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import InternetSearchForm from './InternetSearchForm';
import InternetResult from './InternetResult';
import TvmSearchForm from './TvmSearchForm';
import TvmResult from './TvmResult';
import { internetConfig, tvmConfig } from '../config/config';

export default function InternetCalculator() {
  const navigate = useNavigate();
  const { state } = useLocation();

  // 초기 전달된 state 복원
  const [internetPlan, setInternetPlan] = useState(state?.internetPlan || null);
  const [tvPlan, setTvPlan] = useState(state?.tvPlan || null);
  const [tvStb, setTvStb] = useState(state?.tvStb || '');

  // 약정 기간(인터넷 기준)
  const terms = internetPlan && internetPlan.pricing
    ? Object.keys(internetPlan.pricing)
    : [];

  // 인터넷 월합 계산
  const calcInternetTotal = (term) => {
    if (!internetPlan) return 0;
    const { pricing, id } = internetPlan;
    const isAltt = id.startsWith('altt_');
    // 기본 요금
    const base = isAltt
      ? (internetConfig.plans.find(p => p.id === id.replace('altt_', ''))?.pricing['3년'] || 0)
      : (pricing[term] || 0);
    // 알뜰 할인
    const discountMap = { altt_essence: 3300, altt_basic: 3000, altt_slim: 2750 };
    const discount = isAltt ? (discountMap[id] || 0) : 0;
    // 모뎀 요금
    const feeCfg = internetConfig.premiumModemFee[id] || internetConfig.generalModemFee[id] || {};
    const modemFee = feeCfg[term] || 0;
    return base - discount + modemFee;
  };

  // TV 월합 계산
  const calcTvTotal = (term) => {
    if (!tvPlan) return 0;
    const { pricing, id } = tvPlan;
    const base = pricing[term] || 0;
    const isAltt = internetPlan?.id.startsWith('altt_');
    // 알뜰 결합 할인
    const discountMap = { genie_tv_slim: 5250, genie_tv_basic: 7000, genie_tv_essence: 8700 };
    const comboDiscount = isAltt ? (discountMap[id] || 0) : 0;
    // 셋톱박스 요금
    const stbPricing = tvmConfig.setTopBoxes?.[tvStb]?.pricing || {};
    const stbFee = stbPricing[term] || 0;
    return base - comboDiscount + stbFee;
  };

  // 1단계: 인터넷 선택 폼
  if (!internetPlan) {
    return (
      <div className="p-6 max-w-3xl mx-auto">
        <h1 className="text-3xl font-bold text-center mb-8">KT 인터넷 계산기</h1>
        <InternetSearchForm onSelect={setInternetPlan} />
        <div className="flex justify-center mt-6">
          <button
            type="button"
            onClick={() => navigate('/')}
            className="bg-gray-200 px-4 py-2 rounded hover:bg-gray-300"
          >메인으로 돌아가기</button>
        </div>
      </div>
    );
  }

  // 2단계: TV 선택 폼
  if (!tvPlan) {
    return (
      <div className="p-6 max-w-3xl mx-auto">
        <h1 className="text-3xl font-bold text-center mb-8">KT 인터넷 계산기</h1>
        <InternetResult plan={internetPlan} />
        <TvmSearchForm onSelect={setTvPlan} />
        <div className="flex justify-center mt-6 space-x-4">
          <button
            type="button"
            onClick={() => setInternetPlan(null)}
            className="bg-gray-200 px-4 py-2 rounded hover:bg-gray-300"
          >다른 인터넷 선택</button>
          <button
            type="button"
            onClick={() => navigate('/')}
            className="bg-gray-200 px-4 py-2 rounded hover:bg-gray-300"
          >메인으로 돌아가기</button>
        </div>
      </div>
    );
  }

  // 3단계: 결합 결과
  return (
    <div className="p-6 max-w-3xl mx-auto">
      <h1 className="text-3xl font-bold text-center mb-8">KT 인터넷 계산기</h1>

      <InternetResult plan={internetPlan} />
      <TvmResult
        plan={tvPlan}
        stbKey={tvStb}
        onStbChange={setTvStb}
        internetPlan={internetPlan}
      />

      {/* 설치비 안내 */}
      <div className="mb-6 text-center text-gray-700">
        <p>인터넷 단품일 경우 평일(주간): <strong>36,000원</strong>, 주말/공휴일: <strong>45,000원</strong></p>
        <p>인터넷+TV 동시 출동일 경우 평일(주간): <strong>56,200원</strong>, 주말/공휴일: <strong>41,000원</strong></p>
      </div>

      {/* 전체 월 결합 총액 */}
      <div className="mb-6">
        <h3 className="text-lg font-semibold mb-4">전체 월 결합 총액 (VAT 포함)</h3>
        <table className="w-full table-auto border-collapse">
          <thead>
            <tr className="bg-gray-100">
              <th className="border px-3 py-2">약정 기간</th>
              {terms.map(term => (
                <th key={term} className="border px-3 py-2">{term}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            <tr>
              <td className="border px-3 py-2 font-semibold">월 총액(원)</td>
              {terms.map(term => (
                <td key={term} className="border px-3 py-2 font-semibold">
                  {((calcInternetTotal(term) + calcTvTotal(term)) || 0).toLocaleString()}
                </td>
              ))}
            </tr>
          </tbody>
        </table>
      </div>

      {/* 액션 버튼 */}
      <div className="flex flex-col items-center space-y-4 mb-8">
        <button
          type="button"
          onClick={() => setTvPlan(null)}
          className="w-48 bg-purple-600 text-white py-2 rounded hover:bg-purple-700"
        >지니TV 변경하기</button>

        <button
          type="button"
          className="w-48 bg-indigo-600 text-white py-2 rounded hover:bg-indigo-700"
        >계산하기</button>

        <button
          type="button"
          onClick={() => { setInternetPlan(null); setTvPlan(null); setTvStb(''); }}
          className="w-48 bg-blue-500 text-white py-2 rounded hover:bg-blue-600"
        >다른 플랜 검색하기</button>

        <button
          type="button"
          onClick={() => navigate('/')}
          className="w-48 bg-gray-200 text-gray-700 py-2 rounded hover:bg-gray-300"
        >메인으로 돌아가기</button>
      </div>
    </div>
  );
}
