// src/calculators/TvmResult.jsx
import React from 'react';
import { tvmConfig } from '../config/config';

/**
 * plan: 선택된 TV 플랜 object
 * stbKey: 셋톱박스 ID
 * onStbChange: 셋톱박스 변경 콜백
 * internetPlan: InternetCalculator 로부터 전달된 인터넷 플랜 (or null)
 */
export default function TvmResult({ plan, stbKey, onStbChange, internetPlan }) {
  const { id, name, channel, pricing } = plan;

  // 인터넷 알뜰 플랜 여부
  const isInternetAltt = internetPlan?.id?.startsWith('altt_');
  const tvDiscountMap = {
    genie_tv_slim:    5250,
    genie_tv_basic:  7000,
    genie_tv_essence:8700,
  };
  const tvDiscount = isInternetAltt ? (tvDiscountMap[id] || 0) : 0;

  // 전체 셋톱박스 정의에서 list 생성
  const allStbs = tvmConfig.setTopBoxes || {};
  const stbOptions = Object.entries(allStbs).map(([key, { label }]) => ({ id: key, name: label }));

  // 선택된 셋톱박스 요금표 (VAT 포함)
  const selectedStbPricing = tvmConfig.setTopBoxes?.[stbKey]?.pricing || {};

  const terms = Object.keys(pricing);

  return (
    <div className="mb-8">
      <h2 className="text-xl font-semibold mb-4">
        선택된 지니TV: {name} ({channel}채널)
      </h2>

      {/* 셋톱박스 선택 */}
      <div className="mb-4">
        <label className="block mb-1 font-medium">셋톱박스 선택</label>
        <select
          value={stbKey}
          onChange={e => onStbChange(e.target.value)}
          className="w-full border rounded p-2"
        >
          <option value="">-- 셋톱박스 선택 --</option>
          {stbOptions.map(opt => (
            <option key={opt.id} value={opt.id}>
              {opt.name}
            </option>
          ))}
        </select>
      </div>

      <table className="w-full table-auto border-collapse">
        <thead>
          <tr className="bg-gray-100">
            <th className="border px-3 py-2">약정 기간</th>
            {terms.map(term => (
              <th key={term} className="border px-3 py-2">{term}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          {/* 기본 월 요금 */}
          <tr>
            <td className="border px-3 py-2">월 요금(원)</td>
            {terms.map((term, idx) => (
              <td key={idx} className="border px-3 py-2">
                {pricing[term]?.toLocaleString() ?? '-'}
              </td>
            ))}
          </tr>

          {/* 알뜰 결합 할인 */}
          {isInternetAltt && tvDiscount > 0 && (
            <tr>
              <td className="border px-3 py-2 text-red-600">알뜰 결합 할인(원)</td>
              {terms.map((_, idx) => (
                <td key={idx} className="border px-3 py-2 text-red-600">
                  -{tvDiscount.toLocaleString()}
                </td>
              ))}
            </tr>
          )}

          {/* 셋톱박스 요금 */}
          <tr>
            <td className="border px-3 py-2">셋톱박스 (VAT 포함)</td>
            {terms.map((term, idx) => (
              <td key={idx} className="border px-3 py-2">
                {selectedStbPricing[term] != null ? selectedStbPricing[term].toLocaleString() : '-'}
              </td>
            ))}
          </tr>

          {/* 월 총금액 */}
          <tr>
            <td className="border px-3 py-2 font-semibold">월 총금액 (VAT 포함)</td>
            {terms.map((term, idx) => {
              const base = pricing[term] || 0;
              const fee  = selectedStbPricing[term] || 0;
              const total = base - (isInternetAltt ? tvDiscount : 0) + fee;
              return (
                <td key={idx} className="border px-3 py-2 font-semibold">
                  {total.toLocaleString()}
                </td>
              );
            })}
          </tr>
        </tbody>
      </table>
    </div>
  );
}
